node - <<'NODE'
const inf=require('/app/vendor/infographic.min.js');
const syntax=`infographic list-grid-badge-card
data
  title Test
  lists
    - label A
      value 12
      desc Alpha
    - label B
      value 34
      desc Beta
theme
  palette #1f4e79 #0e7490 #d89c24`;
const parsed=inf.parseSyntax(syntax);
console.log('parsed keys', Object.keys(parsed));
console.log(JSON.stringify(parsed).slice(0,1000));
const svg=inf.exportToSVG(parsed);
console.log(typeof svg, svg && svg.then?'promise':'sync');
if (svg && svg.then) svg.then(s=>console.log(String(s).slice(0,500))).catch(e=>console.error(e)); else console.log(String(svg).slice(0,500));
